{
    Console.Write("A1 ");
    await next(ctx);
    Console.Write("A2 ");
});
app.Use(async (ctx, next) =>
{
    Console.Write("B1 ");
    if (ctx.Request.Path == "/stop") return;
    await next(ctx);
    Console.Write("B2 ");
});
app.Run(_ =>
{
    Console.Write("END ");
    return Task.CompletedTask;
});
