#:package Microsoft.Extensions.Logging@10.0.0
using Microsoft.Extensions.Logging;

var captured = new List<string>();
using var factory = LoggerFactory.Create(b => b.SetMinimumLevel(LogLevel.Information).AddProvider(new Cap(captured)));
var logger = factory.CreateLogger("demo");
int id = 42;
logger.LogInformation("Customer {CustomerId} created", id);
logger.LogInformation($"Customer {id} created");
foreach (var line in captured) Console.WriteLine(line);

class Cap(List<string> sink) : ILoggerProvider
{
    public ILogger CreateLogger(string name) => new L(sink);
    public void Dispose() { }
    class L(List<string> sink) : ILogger
    {
        public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;
        public bool IsEnabled(LogLevel l) => true;
        public void Log<TState>(LogLevel l, EventId e, TState state, Exception? ex, Func<TState, Exception?, string> f)
        {
            var props = ((IEnumerable<KeyValuePair<string, object?>>)state!)
                .Where(p => p.Key != "{OriginalFormat}").Select(p => p.Key + "=" + p.Value);
            sink.Add($"fields=[{string.Join(",", props)}]");
        }
    }
}

