using Microsoft.AspNetCore.Diagnostics;

var builder = WebApplication.CreateBuilder(new WebApplicationOptions { EnvironmentName = "Production" });
builder.WebHost.UseUrls("http://127.0.0.1:0");
builder.Logging.ClearProviders();
builder.Services.AddProblemDetails();
builder.Services.AddExceptionHandler<CatchAllHandler>();
builder.Services.AddExceptionHandler<ArgumentHandler>();

var app = builder.Build();
app.UseExceptionHandler();
app.MapGet("/", () => { throw new ArgumentException("x"); });
await app.StartAsync();

using var http = new HttpClient { BaseAddress = new Uri(app.Urls.First()) };
var res = await http.GetAsync("/");
Console.WriteLine((int)res.StatusCode);
await app.StopAsync();

class CatchAllHandler : IExceptionHandler
{
    public ValueTask<bool> TryHandleAsync(HttpContext ctx, Exception ex, CancellationToken ct)
    {
        ctx.Response.StatusCode = 500;
        return ValueTask.FromResult(true);
    }
}

class ArgumentHandler : IExceptionHandler
{
    public ValueTask<bool> TryHandleAsync(HttpContext ctx, Exception ex, CancellationToken ct)
    {
        if (ex is not ArgumentException) return ValueTask.FromResult(false);
        ctx.Response.StatusCode = 422;
        return ValueTask.FromResult(true);
    }
}

