static async Task<string> Run(bool exceptionHandlerFirst)
{
    var builder = WebApplication.CreateBuilder(new WebApplicationOptions { EnvironmentName = "Production" });
    builder.WebHost.UseUrls("http://127.0.0.1:0");
    builder.Logging.ClearProviders();
    builder.Services.AddProblemDetails();
    builder.Services.AddExceptionHandler<Handler>();
    var app = builder.Build();
    if (exceptionHandlerFirst) app.UseExceptionHandler();
    app.Use(async (ctx, next) =>
    {
        if (ctx.Request.Path == "/boom") throw new InvalidOperationException("nổ");
        await next();
    });
    if (!exceptionHandlerFirst) app.UseExceptionHandler();
    app.MapGet("/boom", () => "ok");
    await app.StartAsync();
    using var http = new HttpClient { BaseAddress = new Uri(app.Urls.First()) };
    var r = await http.GetAsync("/boom");
    var body = await r.Content.ReadAsStringAsync();
    await app.StopAsync();
    return $"{(int)r.StatusCode} {(body.Length > 0 ? "co-body" : "rong")}";
}

class Handler : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext ctx, Exception ex, CancellationToken ct)
    {
        ctx.Response.StatusCode = 503;
        await ctx.Response.WriteAsync("Loi he thong", ct);
        return true;
    }
}

