#:sdk Microsoft.NET.Sdk.Web
#:property PublishAot=false
using System.Text.Encodings.Web;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Options;

Console.WriteLine("dung: " + await Run(routingFirst: true));
Console.WriteLine("sai: " + await Run(routingFirst: false));

static async Task<string> Run(bool routingFirst)
{
    var builder = WebApplication.CreateBuilder(new WebApplicationOptions { EnvironmentName = "Production" });
    builder.WebHost.UseUrls("http://127.0.0.1:0");
    builder.Logging.ClearProviders();
    builder.Services.AddAuthentication("Demo").AddScheme<AuthenticationSchemeOptions, DemoHandler>("Demo", null);
    builder.Services.AddAuthorization(o => o.FallbackPolicy =
        new AuthorizationPolicyBuilder().RequireAuthenticatedUser().Build());
    var app = builder.Build();
    app.UseAuthentication();
    if (routingFirst) { app.UseRouting(); app.UseAuthorization(); }
    else { app.UseAuthorization(); app.UseRouting(); }
    app.MapGet("/status", () => "ok").AllowAnonymous();
    app.MapGet("/leads", () => "secret");
    await app.StartAsync();
    using var http = new HttpClient { BaseAddress = new Uri(app.Urls.First()) };
    var a = (int)(await http.GetAsync("/status")).StatusCode;
    var b = (int)(await http.GetAsync("/leads")).StatusCode;
    await app.StopAsync();
    return $"{a} {b}";
}

class DemoHandler(IOptionsMonitor<AuthenticationSchemeOptions> o, ILoggerFactory l, UrlEncoder e)
    : AuthenticationHandler<AuthenticationSchemeOptions>(o, l, e)
{
    protected override Task<AuthenticateResult> HandleAuthenticateAsync() =>
        Task.FromResult(AuthenticateResult.NoResult());
}
